 data=(ROOT/'docs/replica/source/home-pageintegrationtrial-cases.json').read_bytes();f=ROOT/'artifacts/replica/windows-download'/('home-pageintegrationsummarycontent-'+nonce+'-cases.json');f.write_bytes(data)
 code=app+"if(@(Get-Process -Name ReplicaProbe -ErrorAction SilentlyContinue|Where-Object{$_.Path-eq($app+'\\ReplicaProbe.exe')}).Count){throw 'Owned process already live'};if((Get-FileHash ($app+'\\ReplicaProbe.dll') -Algorithm SHA256).Hash-ne "+q(meta['binarySha256'].upper())+"){throw 'Frozen binary changed'};Remove-Item (Join-Path $out 'pageintegration-*.json'),(Join-Path $out 'cleanup.json'),(Join-Path $out 'failed-state.json') -ErrorAction SilentlyContinue;$cases=Join-Path $out 'cases.json';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+f.name)+" -OutFile $cases;Remove-Item Env:DBMV_HEADLESS -ErrorAction SilentlyContinue;"+peer_env+"$env:DBMV_SUMMARY_CONTENT_ONLY='1';$p=Start-Process -FilePath ($app+'\\ReplicaProbe.exe') -ArgumentList @('--pageintegration-window',$cases,$out,'--summary-content-only') -WorkingDirectory $app -PassThru;$record=[pscustomobject]@{pid=$p.Id;path=($app+'\\ReplicaProbe.exe');nonce="+q(nonce)+"};$record|ConvertTo-Json|Set-Content -Encoding UTF8 (Join-Path $out 'launch.json');$record|ConvertTo-Json -Compress;"
