  code=code[:code.index("$p=Start-Process")]+("$env:DBMV_SUMMARY_CONTENT_TARGET="+q(a.target)+";" if a.target else "Remove-Item Env:DBMV_SUMMARY_CONTENT_TARGET -ErrorAction SilentlyContinue;")
