  code+="$headOut=Join-Path $app "+q('summary-content-headless-'+nonce)+";New-Item -ItemType Directory $headOut -Force|Out-Null;$p=Start-Process -FilePath ($app+'\\ReplicaProbe.exe') -ArgumentList @('--pageintegration',$cases,$headOut,'--summary-content-only') -WorkingDirectory $app -PassThru -RedirectStandardOutput (Join-Path $headOut 'stdout.txt') -RedirectStandardError (Join-Path $headOut 'stderr.txt');if(!$p.WaitForExit(20000)){throw 'Owned bounded headless not exited; no relaunch'};[pscustomobject]@{exitCode=$p.ExitCode;pid=$p.Id;ownedHeadlessProcess=@(Get-Process -Id $p.Id -ErrorAction SilentlyContinue).Count}|ConvertTo-Json -Compress;foreach($f in Get-ChildItem $headOut -Filter '*.json'){[pscustomobject]@{name=$f.Name;content=(ReadShared $f.FullName)}|ConvertTo-Json -Compress};foreach($f in Get-ChildItem $headOut -Filter '*.png'){[pscustomobject]@{name=$f.Name;pngBase64=[Convert]::ToBase64String([IO.File]::ReadAllBytes($f.FullName))}|ConvertTo-Json -Compress};"
