served=ROOT/'artifacts/replica/windows-download'/('home-pageintegrationsummarycontent-'+nonce+'-command.txt');served.write_text(code);sha=hashlib.sha256(served.read_bytes()).hexdigest().upper();loader="$ProgressPreference='SilentlyContinue';$f=Join-Path $env:TEMP "+q(served.name)+";try{Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+served.name)+" -OutFile $f;if((Get-FileHash $f -Algorithm SHA256).Hash-ne "+q(sha)+"){throw 'Owned command hash mismatch'};& ([scriptblock]::Create([IO.File]::ReadAllText($f,[Text.Encoding]::UTF8)))}finally{Remove-Item $f -ErrorAction SilentlyContinue};"
